<template>
  <section><div class="catalog-heading"><div><p class="eyebrow">AI 问答管理</p><h1>问答统计</h1><p class="muted">以北京时间自然日统计。重试单独计尝试，未评价回答不计满意度分母。</p></div></div><form class="statistics-filter" @submit.prevent="load"><label>开始日期<input v-model="from" required type="date"></label><label>结束日期<input v-model="to" required type="date"></label><button class="secondary-button" :disabled="loading">查询</button><span class="field-hint">最长180天，回答结果按尝试创建日归属。</span></form><PageStatus :loading="loading" :error="error" @retry="load" /><template v-if="data"><div class="ai-metrics"><article><span>唯一提问</span><strong>{{ data.questions }}</strong><small>接受成功的问题，含输入拦截</small></article><article><span>回答尝试</span><strong>{{ data.attempts }}</strong><small>主动重试 {{ data.retries }} 次</small></article><article><span>回答成功率</span><strong>{{ percent(data.successRate) }}</strong><small>成功 {{ data.successful }} / 终态 {{ data.attempts - data.processing }}</small></article><article><span>用户满意度</span><strong>{{ percent(data.satisfaction) }}</strong><small>有帮助 {{ data.helpful }} / 已评价 {{ data.rated }}</small></article><article><span>评价覆盖率</span><strong>{{ percent(data.feedbackCoverage) }}</strong><small>已评价 / 完成回答</small></article><article><span>平均完成耗时</span><strong>{{ ms(data.averageMs) }}</strong><small>首内容 {{ ms(data.firstContentMs) }}，缺失不计零</small></article></div><div class="ai-result-breakdown"><span>基础回答 <b>{{ data.degraded }}</b></span><span>失败 <b>{{ data.failed }}</b></span><span>已停止 <b>{{ data.cancelled }}</b></span><span>拦截 <b>{{ data.blocked }}</b></span><span>处理中 <b>{{ data.processing }}</b></span></div><section class="editor-section"><h2>每日提问与回答趋势</h2><div ref="trendElement" class="ai-chart" role="img" aria-label="每日提问、回答尝试及失败趋势"></div><p v-if="!data.questions && !data.attempts" class="muted">此区间暂无问答数据。</p></section><div class="ai-stat-columns"><section class="editor-section"><h2>咨询场景</h2><div ref="sceneElement" class="ai-chart ai-scene-chart" role="img" aria-label="咨询场景分布"></div><p v-if="!data.scenes.length" class="muted">暂无场景样本。</p></section><section class="editor-section"><h2>高频问题与主题</h2><p class="field-hint">优先归组已命中FAQ，其余按安全场景归组，不显示私人单号或地址。</p><ol class="ai-topics"><li v-for="(topic, index) in data.topics" :key="topic.topic"><span class="topic-index">{{ index + 1 }}</span><strong>{{ topic.topic }}</strong><b>{{ topic.count }}</b></li></ol><p v-if="!data.topics.length" class="muted">暂无高频问题样本。</p></section></div><details class="statistics-method"><summary>指标口径与数据保留</summary><p>同一客户端请求标识和相同负载只接受一次。主动重试新增尝试，沿用原问题，不重复计提问。COMPLETED与DEGRADED为成功，FAILED、CANCELLED、BLOCKED均为终态；处理中排除成功率分母。</p><p>满意度为当前有帮助 / 当前已评价回答；评价可修改，未评价不进入分母。删除或过期会清除正文及身份关联，并保留匿名统计和最后有效评价，因此历史删除不会使统计消失。无分母显示“无样本”。</p></details></template></section>
</template>
<script setup lang="ts">
import { nextTick, onMounted, onUnmounted, ref } from 'vue'
import * as echarts from 'echarts'
import PageStatus from '../components/PageStatus.vue'
import { statistics, aiSceneLabel, type Statistics } from '../api/admin-ai'
import { errorMessage } from '../api/catalog'
function localDate(date: Date) { return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}` }
const today = new Date(), week = new Date(today); week.setDate(today.getDate() - 6)
const from = ref(localDate(week)), to = ref(localDate(today)), data = ref<Statistics | null>(null), loading = ref(false), error = ref(''), trendElement = ref<HTMLElement>(), sceneElement = ref<HTMLElement>()
let trend: echarts.ECharts | undefined, scene: echarts.ECharts | undefined, observer: ResizeObserver | undefined
const percent = (value: number | null) => value === null ? '无样本' : (value * 100).toFixed(1) + '%'
const ms = (value: number | null) => value === null ? '无样本' : value < 1000 ? Math.round(value) + 'ms' : (value / 1000).toFixed(1) + 's'
async function load() { loading.value = true; error.value = ''; try { data.value = await statistics({ from: from.value, to: to.value }); await nextTick(); draw() } catch (failure) { data.value = null; observer?.disconnect(); observer = undefined; trend?.dispose(); scene?.dispose(); trend = undefined; scene = undefined; error.value = errorMessage(failure) } finally { loading.value = false } }
function draw() {
  if (!data.value || !trendElement.value || !sceneElement.value) return
  trend ??= echarts.init(trendElement.value); scene ??= echarts.init(sceneElement.value)
  trend.setOption({ color: ['#4e8b50', '#b1c296', '#cd9866'], tooltip: { trigger: 'axis', renderMode: 'richText' }, legend: { bottom: 0, textStyle: { fontSize: 11, color: '#87947c' } }, grid: { left: 40, right: 20, top: 20, bottom: 60 }, xAxis: { type: 'category', data: data.value.trend.map(item => item.date.slice(5)), axisLabel: { color: '#89957e', fontSize: 10 }, axisLine: { lineStyle: { color: '#e0e8d8' } }, axisTick: { show: false } }, yAxis: { type: 'value', minInterval: 1, axisLabel: { color: '#89957e', fontSize: 10 }, splitLine: { lineStyle: { color: '#eef2e8' } } }, series: [{ name: '唯一提问', type: 'line', smooth: true, data: data.value.trend.map(item => item.questions) }, { name: '回答尝试', type: 'line', smooth: true, data: data.value.trend.map(item => item.attempts) }, { name: '失败', type: 'bar', barMaxWidth: 20, data: data.value.trend.map(item => item.failed) }] }, true)
  scene.setOption({ color: ['#5d8c4d', '#9cb882', '#d0dcb6', '#e3c991', '#b6c7a4'], tooltip: { trigger: 'item', renderMode: 'richText' }, legend: { bottom: 0, textStyle: { fontSize: 11, color: '#7d8e70' } }, series: [{ type: 'pie', radius: ['38%', '64%'], center: ['50%', '43%'], label: { fontSize: 11, color: '#728666' }, data: data.value.scenes.map(item => ({ name: aiSceneLabel(item.scene), value: item.count })) }] }, true)
  if (!observer) { observer = new ResizeObserver(() => { trend?.resize(); scene?.resize() }); observer.observe(trendElement.value); observer.observe(sceneElement.value) }
}
onMounted(load); onUnmounted(() => { observer?.disconnect(); trend?.dispose(); scene?.dispose() })
</script>
<style scoped>
.statistics-filter{display:flex;align-items:end;flex-wrap:wrap;gap:14px;margin:23px 0}.statistics-filter label{display:grid;gap:6px;font-size:11px;color:#7b8d70}.statistics-filter input{border:1px solid #d7e2cf;border-radius:6px;padding:9px 11px;font:inherit;background:white}.ai-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin:22px 0}.ai-metrics article{padding:20px 22px;background:#f5f8ef;border-top:2px solid #c2d4ad}.ai-metrics span{display:block;font-size:12px;color:#778a67}.ai-metrics strong{display:block;font-size:30px;line-height:1.5;margin:8px 0;color:#3c6436;font-weight:500}.ai-metrics small{font-size:10px;color:#93a186;line-height:1.7}.ai-result-breakdown{display:flex;gap:25px;flex-wrap:wrap;padding:5px 0 18px;color:#819371;font-size:12px}.ai-result-breakdown b{margin-left:10px;color:#557543}.ai-chart{height:300px;width:100%;min-width:0}.ai-stat-columns{display:grid;grid-template-columns:1fr 1fr;gap:30px}.ai-stat-columns>section{min-width:0}.ai-topics{list-style:none;padding:0;margin:18px 0}.ai-topics li{display:flex;align-items:center;gap:12px;padding:13px 0;border-bottom:1px solid #e8eee0;font-size:12px;color:#6c815b}.topic-index{font-size:10px;color:#a5b298}.ai-topics strong{font-weight:400;flex:1;overflow-wrap:anywhere}.ai-topics b{font-weight:500}.statistics-method{margin-top:25px;font-size:11px;line-height:1.9;color:#8a987e}.statistics-method summary{cursor:pointer}@media(max-width:800px){.ai-metrics{grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.ai-metrics article{padding:14px 15px}.ai-metrics strong{font-size:25px}.ai-stat-columns{grid-template-columns:1fr;gap:0}.ai-result-breakdown{gap:16px}.statistics-filter .field-hint{width:100%}}
</style>
